#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto applyOp = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np(n);
        // [C(y)] [B(middle)] [A(x)]
        for(int i=0;i<y;i++) np[i] = p[n-y+i];
        int mid = n-x-y;
        for(int i=0;i<mid;i++) np[y+i] = p[x+i];
        for(int i=0;i<x;i++) np[y+mid+i] = p[i];
        p = np;
    };

    for(int k=0; k<n-1; k++){
        int pos=-1;
        for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
        if(pos==k) continue;

        // Move element from pos to position k
        // Step 1: move to n-1 if not there
        if(pos != n-1){
            // Use x=pos+1, y=1, need x+y<n => pos+2<n => pos<n-2
            // Element at pos is in prefix A (size x=pos+1), goes to n-x+pos = n-1. 
            if(pos <= n-3){
                applyOp(pos+1, 1);
                pos = n-1;
            } else {
                // pos == n-2, use x=1, y=2: element at n-2 is in suffix C(y=2), goes to pos-(n-2)=0
                applyOp(1, 2);
                // element went to position 0... then need to get to k
                pos = 0;
                if(pos == k) continue;
                // now move from 0 to n-1: x=1, y=1 if n>=3
                if(n>=3){ applyOp(1,1); pos=n-1; }
            }
        }
        // Step 2: element at n-1, move to position k
        // x=k, y=1: element at n-1 in C(y=1), goes to 0. Then middle shifts. Actually:
        // x=k+1, y=1, need k+2<n. Element at n-1 in C, goes to position 0... no.
        // C has y=1 elements starting at n-1. Goes to position 0. We want position k.
        // Use x=k, y=1 (k>=1): element goes to pos 0, not k.
        // Actually: np[0]=p[n-1], then B from p[k..n-2], then A from p[0..k-1]
        // Element goes to 0, first k elements go to end. Not right.
        // Use y = n-k: element at n-1 is in C(y=n-k), goes to pos n-1-(n-k)= k-1... 
        {
            int y = n-1-k;
            int x = 1;
            if(x+y<n && y>=1){ applyOp(x,y); }
            // element at n-1 in C(y=n-1-k), goes to n-1-(n-1-k)=k. 
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
